// Runs the shared conformance fixtures against extension/lib/extract.js.
// Expected snapshots were generated by the retired Python engine and remain frozen.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { JSDOM } from 'jsdom';
import '../../extension/lib/extract.js';

const { extract, profileApplies, validateProfile } = globalThis.PowerLoaderExtract;
const root = new URL('../../', import.meta.url);
const read = (p) => readFileSync(new URL(p, root), 'utf8');
const json = (p) => JSON.parse(read(p));
const template = (name) => json(`extension/templates/${name}.json`);
const expectedPath = (name) => `fixtures/expected/${name.replace(/ /g, '-').replace(/[()]/g, '')}.json`;
const parse = (html, url) => new JSDOM(html, { url: url || 'https://example.invalid/' }).window.document;

for (const c of json('fixtures/dsl-cases.json')) {
  test(`dsl: ${c.name}`, () => {
    const out = extract(parse(c.html, c.url), { fields: c.fields }, { baseUrl: c.url });
    assert.deepEqual(out.data, c.expected);
  });
}

for (const c of json('fixtures/pages.json')) {
  test(`page: ${c.name}`, () => {
    const profile = template(c.template);
    const doc = parse(read(`fixtures/${c.page}`), c.url);
    assert.ok(profileApplies(profile, c.url, doc), 'profile should apply');
    const out = extract(doc, profile, { baseUrl: c.url });
    assert.deepEqual(out.data, json(expectedPath(c.name)));
  });
}

test('templates are valid and indexed', () => {
  const files = readdirSync(new URL('extension/templates/', root)).filter((f) => f !== 'index.json');
  assert.deepEqual([...json('extension/templates/index.json')].sort(), files.map((f) => f.replace(/\.json$/, '')).sort());
  for (const f of files) assert.deepEqual(validateProfile(json(`extension/templates/${f}`)), [], f);
});

test('errors are diagnostics, not exceptions', () => {
  const out = extract(parse('<p>x</p>'), { fields: { a: 'p[[[', b: 'p | nosuch', c: 'p | regex:(', d: 5 } });
  assert.deepEqual(out.data, { a: null, b: null, c: null, d: null });
  assert.deepEqual(out.diagnostics.map((d) => d.level), ['error', 'error', 'error', 'error']);
});

// ------------------------------------------------------------------ fill profiles
const { resolveFill } = globalThis.PowerLoaderExtract;
const fillUnit = json('fixtures/fill-unit.json');

for (const c of fillUnit.cases) {
  test(`fill: ${c.name}`, () => {
    const plan = resolveFill({ fields: { '#x': c.spec } }, fillUnit.records);
    assert.deepEqual(plan.fields[0].value, c.expected);
  });
}

for (const c of json('fixtures/fill-pages.json')) {
  test(`fill page: ${c.name}`, () => {
    const plan = resolveFill(template(c.template), c.records);
    assert.deepEqual({ fields: plan.fields, lists: plan.lists }, json(expectedPath(`fill ${c.name}`)));
  });
}

test('fill: relative paths inside lists', () => {
  const profile = { lists: [{ source: 'Person.relatedTo', rows: 'tr', fields: { a: '.name', b: 'Person.name' } }] };
  assert.deepEqual(resolveFill(profile, fillUnit.records).lists[0].items, [
    [{ target: 'a', value: 'John' }, { target: 'b', value: 'Jane Q Doe' }],
    [{ target: 'a', value: 'Amy' }, { target: 'b', value: 'Jane Q Doe' }],
  ]);
});
